// Lens s a = { getter :: s -> a, setter :: (a -> a) -> s -> s }
// lensKey :: String -> Lens s a
const lensKey = (key) => ({
  getter: (data) => data[key],
  // setter всегда принимает функцию и не проверяет, что ему передали
  setter: (fn) => (data) => {
    const copy = { ...data }
    copy[key] = fn(data[key])
    return copy
  },
})

